import { Task } from '../domain/task';
import { TaskStatusValue } from '../domain/task-status';

export interface CreateUserInput { name: string; }
export interface CreateProjectInput { name: string; }
export interface CreateTaskInput {
  title: string;
  description: string;
  dueDate?: string;
  status?: string;
  assigneeId?: string;
}
export interface ListTasksInput { status?: string; assigneeId?: string; }

export interface UserDto { id: string; name: string; }
export interface ProjectDto { id: string; name: string; }
export interface TaskDto {
  id: string;
  projectId: string;
  title: string;
  description: string;
  dueDate?: string;
  status: TaskStatusValue;
  assigneeId?: string;
}

export const toTaskDto = (task: Task): TaskDto => ({
  id: task.id,
  projectId: task.projectId,
  title: task.title,
  description: task.description,
  dueDate: task.dueDate?.toISOString(),
  status: task.getStatus().value,
  assigneeId: task.assigneeId,
});

